export const LIFE_SCIENCES_BASICS_B_QUIZZES = [
  {
    id:`bb119`, cat:`Life Sciences`, title:`Osmosis & Diffusion in Everyday Life`, diff:`Easy`,
    qs:[
      { q:`Diffusion is the movement of particles from:`, ch:[`an area of high concentration to an area of low concentration`,`low concentration to high concentration only`,`inside a cell to outside only`,`hot regions to cold regions`], ans:0, exp:`Diffusion follows the concentration gradient, moving from high to low concentration until equilibrium, and requires no cellular energy.` },
      { q:`Osmosis specifically refers to the diffusion of:`, ch:[`salt ions across a cell membrane`,`water molecules across a semipermeable membrane`,`proteins out of a cell`,`oxygen molecules into the bloodstream`], ans:1, exp:`Osmosis is the special case of diffusion involving water crossing a selectively permeable membrane from an area of lower solute concentration to higher solute concentration.` },
      { q:`A red blood cell placed in a hypotonic solution (more dilute than the cell) will:`, ch:[`shrink and shrivel`,`stay exactly the same size`,`swell and possibly burst`,`turn into a different cell type`], ans:2, exp:`In a hypotonic solution, water moves into the cell by osmosis because the outside has a lower solute concentration than the inside, causing the cell to swell and potentially burst.` },
      { q:`A plant cell placed in a hypertonic solution (saltier than the cell) loses water and its membrane pulls away from the cell wall, a process called:`, ch:[`turgor`,`osmoregulation`,`lysis`,`plasmolysis`], ans:3, exp:`Plasmolysis occurs when a plant cell loses water in a hypertonic environment, causing the cell membrane to shrink away from the rigid cell wall.` },
      { q:`Which everyday example best demonstrates diffusion?`, ch:[`A drop of food coloring spreading through a glass of water`,`A car engine burning gasoline`,`A battery storing electrical energy`,`A rock rolling downhill`], ans:0, exp:`Food coloring spreading evenly through water is a classic diffusion example; molecules move from the concentrated drop into the surrounding water until evenly distributed.` },
      { q:`Why does a wilted plant perk back up after watering?`, ch:[`The soil temperature increases`,`Water moves into root cells by osmosis, restoring turgor pressure`,`Sunlight reactivates chlorophyll`,`Carbon dioxide levels drop`], ans:1, exp:`Watering increases water concentration around the roots, so water moves into root cells by osmosis, restoring the internal pressure (turgor) that keeps the plant upright.` },
      { q:`Facilitated diffusion differs from simple diffusion in that facilitated diffusion:`, ch:[`requires ATP energy`,`moves substances against their gradient`,`uses membrane proteins to help specific molecules cross`,`only occurs in plant cells`], ans:2, exp:`Facilitated diffusion still moves substances down their concentration gradient without ATP, but relies on channel or carrier proteins to help larger or charged molecules cross the membrane.` },
      { q:`Why do doctors use isotonic saline (0.9% NaCl) for IV fluids instead of pure water?`, ch:[`Pure water is more expensive to produce`,`Saline tastes better`,`Water cannot enter veins`,`Pure water would be hypotonic and cause red blood cells to swell and burst`], ans:3, exp:`Isotonic saline has the same solute concentration as blood cells, so no net water movement occurs, while pure water is hypotonic relative to cells and would cause them to swell and lyse.` },
      { q:`Which factor does NOT speed up the rate of diffusion?`, ch:[`Increasing the size of the diffusing molecule`,`Increasing temperature`,`Increasing the concentration gradient`,`Decreasing the distance molecules must travel`], ans:0, exp:`Larger molecules diffuse more slowly, not faster. Higher temperature, steeper gradients, and shorter distances all increase diffusion rate.` },
      { q:`A slug sprinkled with salt shrivels up because:`, ch:[`Salt is toxic to slug DNA`,`Water leaves the slug's cells by osmosis into the hypertonic salt`,`The salt burns the slug's skin`,`Salt causes the slug's cells to divide rapidly`], ans:1, exp:`Salt on the slug's skin creates a hypertonic environment outside its cells, so water rushes out of the cells by osmosis, dehydrating and shriveling the slug.` },
      { q:`Which statement about diffusion and osmosis is TRUE?`, ch:[`Both processes always require energy input`,`Osmosis moves solutes while diffusion moves only water`,`Osmosis is a specific type of diffusion involving water`,`Diffusion only happens in living cells`], ans:2, exp:`Osmosis is a specific case of diffusion applying to water movement across selectively permeable membranes, while diffusion more broadly applies to any particle moving down a concentration gradient; neither requires energy.` },
    ]
  },
  {
    id:`bb120`, cat:`Life Sciences`, title:`Homeostasis of Blood Sugar: An Intro to Diabetes`, diff:`Medium`,
    qs:[
      { q:`Which organ produces both insulin and glucagon?`, ch:[`The thyroid gland`,`The pancreas`,`The liver`,`The kidneys`], ans:1, exp:`The pancreas contains islets of Langerhans, with beta cells that produce insulin and alpha cells that produce glucagon.` },
      { q:`After eating a meal, blood glucose rises. The body responds by releasing:`, ch:[`thyroid hormone, which increases metabolism`,`glucagon, which raises blood sugar further`,`insulin, which helps cells absorb glucose and lowers blood sugar`,`adrenaline, which stops digestion`], ans:2, exp:`Rising blood glucose triggers insulin release from the pancreas; insulin signals cells to take up glucose from the blood, lowering blood sugar levels.` },
      { q:`Glucagon's main effect on blood sugar is to:`, ch:[`convert glucose into fat`,`lower it by promoting glucose uptake into cells`,`have no effect on blood glucose`,`raise it by triggering the liver to release stored glucose`], ans:3, exp:`Glucagon is released when blood sugar is low. It signals the liver to break down glycogen stores and release glucose into the bloodstream.` },
      { q:`Insulin and glucagon work together as an example of:`, ch:[`negative feedback`,`positive feedback`,`osmosis`,`natural selection`], ans:0, exp:`Insulin and glucagon act as opposing hormones in a negative feedback loop, adjusting blood glucose back toward a stable set point whenever it rises or falls.` },
      { q:`Type 1 diabetes is best described as:`, ch:[`a contagious viral infection`,`an autoimmune condition where the body destroys insulin-producing beta cells`,`a disease caused entirely by eating too much sugar`,`a condition where the body makes too much insulin`], ans:1, exp:`Type 1 diabetes results when the immune system mistakenly attacks and destroys the insulin-producing beta cells of the pancreas.` },
      { q:`Type 2 diabetes is most closely associated with:`, ch:[`a genetic inability to produce glucagon`,`complete absence of insulin production from birth`,`cells becoming less responsive to insulin (insulin resistance)`,`an autoimmune attack on the liver`], ans:2, exp:`Type 2 diabetes typically develops when body cells become resistant to insulin's effects, so glucose is not efficiently taken up, even though the pancreas may still produce insulin.` },
      { q:`A person with untreated high blood sugar (hyperglycemia) would most likely experience:`, ch:[`slowed heart rate`,`shivering and low body temperature`,`immediate loss of consciousness within seconds`,`excessive thirst and frequent urination`], ans:3, exp:`High blood glucose causes the kidneys to excrete excess sugar in urine, pulling extra water with it, leading to frequent urination and increased thirst.` },
      { q:`Why might a person with diabetes need to monitor their blood sugar and sometimes inject insulin?`, ch:[`Because their body cannot properly regulate glucose on its own`,`To increase their glucagon levels`,`To slow down their metabolism`,`To prevent their pancreas from growing`], ans:0, exp:`Diabetes disrupts the body's normal insulin-based feedback system, so external monitoring and sometimes insulin injections are needed to keep blood glucose within a safe range.` },
      { q:`Which of the following is a normal fasting blood glucose range for a healthy person (roughly)?`, ch:[`500-600 mg/dL`,`70-100 mg/dL`,`300-400 mg/dL`,`0-10 mg/dL`], ans:1, exp:`A typical healthy fasting blood glucose level is roughly 70-100 mg/dL. Levels consistently above this range may indicate diabetes.` },
      { q:`Where does most excess glucose get stored for later use in the body?`, ch:[`It cannot be stored and is always excreted`,`As protein in muscle tissue`,`As glycogen in the liver and muscles`,`As glucose crystals in the kidneys`], ans:2, exp:`Excess glucose is converted to glycogen, a storage form of carbohydrate, and stored primarily in the liver and skeletal muscles.` },
      { q:`What is hypoglycemia?`, ch:[`Excess insulin production only in type 1 diabetes`,`Abnormally high blood pressure`,`Excess glucagon production`,`Abnormally low blood glucose levels`], ans:3, exp:`Hypoglycemia refers to blood glucose dropping below normal levels, which can cause shakiness, confusion, and weakness because the brain relies heavily on a steady glucose supply.` },
    ]
  },
  {
    id:`bb121`, cat:`Life Sciences`, title:`The Cardiovascular System: How the Heart Works`, diff:`Easy`,
    qs:[
      { q:`How many chambers does the human heart have?`, ch:[`Three`,`Six`,`Four`,`Two`], ans:2, exp:`The human heart has four chambers: two atria (upper) and two ventricles (lower), which pump blood through pulmonary and systemic circuits.` },
      { q:`Which chamber of the heart pumps oxygen-rich blood out to the entire body?`, ch:[`Right ventricle`,`Left atrium`,`Right atrium`,`Left ventricle`], ans:3, exp:`The left ventricle has the thickest, most muscular wall because it must generate enough force to pump oxygenated blood through the systemic circulation to the whole body.` },
      { q:`Blood vessels that carry blood away from the heart are called:`, ch:[`arteries`,`venules`,`veins`,`capillaries`], ans:0, exp:`Arteries carry blood away from the heart, typically under higher pressure, and have thicker, more elastic walls than veins.` },
      { q:`The exchange of oxygen, carbon dioxide, and nutrients between blood and body tissues occurs in the:`, ch:[`veins`,`capillaries`,`arteries`,`heart chambers`], ans:1, exp:`Capillaries are the smallest blood vessels, with walls only one cell thick, allowing gases and nutrients to diffuse easily between blood and surrounding tissues.` },
      { q:`Which type of blood vessel typically contains valves to prevent backflow of blood?`, ch:[`Capillaries`,`Aorta`,`Veins`,`Arteries`], ans:2, exp:`Veins carry blood back to the heart, often against gravity and at low pressure, so many contain one-way valves that prevent blood from flowing backward.` },
      { q:`The heart's natural pacemaker, which sets the rhythm of each heartbeat, is called the:`, ch:[`bundle of His`,`Purkinje fibers`,`AV node`,`sinoatrial (SA) node`], ans:3, exp:`The sinoatrial (SA) node, located in the right atrium, generates the electrical signal that triggers each heartbeat and sets the heart's natural pace.` },
      { q:`Pulmonary circulation refers to the path of blood:`, ch:[`between the heart and the lungs`,`from the digestive system to the liver`,`from the heart to the whole body and back`,`only within the heart's chambers`], ans:0, exp:`Pulmonary circulation carries deoxygenated blood from the right side of the heart to the lungs to pick up oxygen, then returns it to the left side of the heart.` },
      { q:`Heart valves function to:`, ch:[`filter waste from the blood`,`prevent blood from flowing backward between chambers`,`generate the heartbeat's electrical signal`,`carry oxygen to heart muscle`], ans:1, exp:`Heart valves open and close in sequence to ensure blood flows in one direction through the heart, preventing backflow.` },
      { q:`Blood pressure is typically reported as two numbers (e.g., 120/80). The higher (top) number represents:`, ch:[`resting heart rate`,`total blood volume`,`systolic pressure, when the heart contracts`,`diastolic pressure, when the heart relaxes`], ans:2, exp:`Systolic pressure (the top number) measures the pressure in arteries when the heart contracts and pushes blood out.` },
      { q:`What is a "pulse" that you feel at your wrist or neck?`, ch:[`The contraction of skeletal muscle`,`A measure of blood oxygen level`,`The sound of blood flowing through veins`,`The rhythmic expansion of an artery caused by each heartbeat`], ans:3, exp:`Each heartbeat forces a surge of blood into the arteries, causing them to briefly expand; this expansion, felt as a pulse, corresponds to the heart rate.` },
      { q:`Which best describes the overall function of the cardiovascular system?`, ch:[`Transporting blood, oxygen, nutrients, and waste throughout the body`,`Producing hormones that control growth`,`Breaking down food into nutrients`,`Filtering waste out of the blood`], ans:0, exp:`The cardiovascular system, made up of the heart and blood vessels, circulates blood to deliver oxygen and nutrients to tissues and carry away waste products.` },
    ]
  },
  {
    id:`bb122`, cat:`Life Sciences`, title:`The Respiratory System: How Breathing Works`, diff:`Easy`,
    qs:[
      { q:`Where does gas exchange between air and blood actually occur in the lungs?`, ch:[`Trachea`,`Bronchi`,`Larynx`,`Alveoli`], ans:3, exp:`Alveoli are tiny, thin-walled air sacs surrounded by capillaries, where oxygen and carbon dioxide diffuse between air and blood.` },
      { q:`The diaphragm is a muscle that, when it contracts, causes you to:`, ch:[`inhale`,`cough`,`swallow`,`exhale`], ans:0, exp:`When the diaphragm contracts, it flattens and moves downward, increasing chest cavity volume and lowering lung pressure, which draws air in.` },
      { q:`Air travels from the throat into the lungs primarily through the:`, ch:[`alveoli`,`trachea (windpipe)`,`diaphragm`,`esophagus`], ans:1, exp:`The trachea, or windpipe, is the main airway connecting the throat to the bronchi, which branch into the lungs toward the alveoli.` },
      { q:`During inhalation, what happens to the volume and pressure inside the chest cavity?`, ch:[`Both volume and pressure increase`,`Both volume and pressure decrease`,`Volume increases and pressure decreases`,`Volume decreases and pressure increases`], ans:2, exp:`As the diaphragm and rib muscles contract, chest cavity volume increases, lowering internal air pressure below atmospheric pressure and causing air to flow in.` },
      { q:`Which gas is primarily exhaled as a waste product of cellular respiration?`, ch:[`Oxygen`,`Nitrogen`,`Hydrogen`,`Carbon dioxide`], ans:3, exp:`Cells produce carbon dioxide as a byproduct of breaking down glucose for energy; this CO2 diffuses into the alveoli and is exhaled.` },
      { q:`What protein in red blood cells is primarily responsible for carrying oxygen through the bloodstream?`, ch:[`Hemoglobin`,`Insulin`,`Keratin`,`Collagen`], ans:0, exp:`Hemoglobin is an iron-containing protein in red blood cells that binds oxygen in the lungs and releases it to tissues throughout the body.` },
      { q:`The airways branch repeatedly inside the lungs, from bronchi into smaller:`, ch:[`arteries`,`bronchioles`,`capillaries`,`alveoli directly`], ans:1, exp:`Bronchi divide into progressively smaller airways called bronchioles, which eventually end in clusters of alveoli where gas exchange occurs.` },
      { q:`Why do alveoli have extremely thin walls and a large surface area?`, ch:[`To produce mucus that traps dust`,`To generate heat for the body`,`To maximize the efficiency of gas diffusion between air and blood`,`To store extra oxygen for later use`], ans:2, exp:`Thin walls minimize diffusion distance, and the huge combined surface area of millions of alveoli allows for rapid, efficient gas exchange.` },
      { q:`What triggers the urge to breathe faster, such as during exercise?`, ch:[`Falling body temperature`,`Rising oxygen levels in the blood`,`Decreased heart rate`,`Rising carbon dioxide levels in the blood`], ans:3, exp:`The brain's respiratory center is highly sensitive to rising CO2 levels, which triggers faster and deeper breathing to expel the excess CO2.` },
      { q:`During exhalation at rest, the diaphragm:`, ch:[`relaxes and moves upward, decreasing chest cavity volume`,`stops functioning entirely`,`contracts sharply to force air out`,`contracts and flattens`], ans:0, exp:`During relaxed exhalation, the diaphragm relaxes and returns to its dome shape, decreasing chest cavity volume and pushing air out of the lungs.` },
      { q:`Which structure prevents food from entering the trachea while swallowing?`, ch:[`The diaphragm`,`The epiglottis`,`The alveoli`,`The bronchioles`], ans:1, exp:`The epiglottis is a flap of tissue that folds down over the trachea during swallowing, directing food into the esophagus instead of the airway.` },
    ]
  },
  {
    id:`bb123`, cat:`Life Sciences`, title:`The Digestive System Journey: Mouth to Gut`, diff:`Easy`,
    qs:[
      { q:`Chemical digestion of carbohydrates begins in the:`, ch:[`mouth, with the enzyme amylase in saliva`,`stomach, with acid`,`small intestine only`,`large intestine`], ans:0, exp:`Saliva contains the enzyme amylase, which starts breaking down starches into smaller sugars as soon as food is chewed in the mouth.` },
      { q:`Food is moved through the esophagus and digestive tract by rhythmic muscle contractions called:`, ch:[`osmosis`,`peristalsis`,`filtration`,`diffusion`], ans:1, exp:`Peristalsis refers to wave-like contractions of smooth muscle that push food along the digestive tract.` },
      { q:`The stomach helps digest food using hydrochloric acid and the enzyme:`, ch:[`amylase`,`lipase only`,`pepsin, which breaks down proteins`,`insulin`], ans:2, exp:`The stomach secretes hydrochloric acid and pepsin, an enzyme that begins breaking down proteins into smaller peptides.` },
      { q:`Most nutrient absorption into the bloodstream happens in the:`, ch:[`stomach`,`large intestine`,`esophagus`,`small intestine`], ans:3, exp:`The small intestine, lined with villi that greatly increase surface area, is where the majority of digested nutrients are absorbed into the blood.` },
      { q:`Villi in the small intestine increase the surface area for:`, ch:[`nutrient absorption`,`mechanical grinding of food`,`acid production`,`bile storage`], ans:0, exp:`Villi (and even smaller microvilli) dramatically increase the small intestine's internal surface area, allowing more efficient nutrient absorption.` },
      { q:`Bile, which helps break down fats, is produced by the liver and stored in the:`, ch:[`pancreas`,`gallbladder`,`stomach`,`spleen`], ans:1, exp:`Bile is produced by the liver but stored and concentrated in the gallbladder, which releases it into the small intestine to help emulsify fats.` },
      { q:`The pancreas contributes to digestion mainly by:`, ch:[`storing bile`,`absorbing water from waste`,`releasing digestive enzymes and bicarbonate into the small intestine`,`producing hydrochloric acid`], ans:2, exp:`The pancreas secretes digestive enzymes and bicarbonate to neutralize stomach acid, delivered into the small intestine.` },
      { q:`After nutrients are absorbed in the small intestine, the remaining undigested material moves into the:`, ch:[`stomach`,`esophagus`,`liver`,`large intestine`], ans:3, exp:`Leftover material that wasn't digested or absorbed passes into the large intestine, where water and some electrolytes are absorbed before elimination.` },
      { q:`A major function of the large intestine is to:`, ch:[`absorb water from remaining waste material`,`digest and absorb most proteins`,`produce bile`,`begin chemical digestion of starch`], ans:0, exp:`The large intestine's main roles are absorbing water and some electrolytes from indigestible food matter and forming and storing feces.` },
      { q:`Which organ is NOT considered part of the digestive tract itself but still plays a key digestive role?`, ch:[`Stomach`,`Pancreas`,`Small intestine`,`Esophagus`], ans:1, exp:`The pancreas is an accessory digestive organ; food never physically passes through it, but it produces enzymes and hormones essential for digestion.` },
      { q:`What is the correct general order that food travels through the digestive system?`, ch:[`Mouth, stomach, esophagus, small intestine`,`Mouth, small intestine, stomach, large intestine`,`Mouth, esophagus, stomach, small intestine, large intestine`,`Esophagus, mouth, stomach, small intestine`], ans:2, exp:`Food travels from the mouth through the esophagus to the stomach, then the small intestine for most digestion and absorption, and finally the large intestine before elimination.` },
    ]
  },
  {
    id:`bb124`, cat:`Life Sciences`, title:`The Nervous System: Neurons & Reflexes Basics`, diff:`Easy`,
    qs:[
      { q:`The basic functional cell of the nervous system is the:`, ch:[`erythrocyte`,`neuron`,`osteocyte`,`myocyte`], ans:1, exp:`Neurons are specialized cells that transmit electrical and chemical signals throughout the nervous system.` },
      { q:`Which part of a neuron typically receives incoming signals from other neurons?`, ch:[`Cell body only`,`Axon terminal`,`Dendrites`,`Myelin sheath`], ans:2, exp:`Dendrites are branch-like extensions that receive signals from neighboring neurons and carry that information toward the cell body.` },
      { q:`The long, thin projection that carries an electrical signal away from the neuron's cell body is the:`, ch:[`nucleus`,`dendrite`,`synapse`,`axon`], ans:3, exp:`The axon is a long fiber that conducts electrical impulses away from the cell body toward the axon terminals.` },
      { q:`The tiny gap between two neurons where chemical signals are transmitted is called the:`, ch:[`synapse`,`axon`,`node of Ranvier`,`dendrite`], ans:0, exp:`At the synapse, an electrical signal triggers the release of neurotransmitters, which cross the gap and bind to receptors on the next neuron.` },
      { q:`Chemical messengers released at synapses that allow neurons to communicate are called:`, ch:[`antibodies`,`neurotransmitters`,`hormones only`,`enzymes`], ans:1, exp:`Neurotransmitters, such as dopamine, serotonin, and acetylcholine, are chemicals released from one neuron that bind to receptors on the next neuron.` },
      { q:`The central nervous system consists of the:`, ch:[`muscles and skin`,`nerves and sensory organs`,`brain and spinal cord`,`heart and blood vessels`], ans:2, exp:`The central nervous system (CNS) is made up of the brain and spinal cord, which process and coordinate information from the rest of the body.` },
      { q:`Nerves that extend throughout the body outside the brain and spinal cord make up the:`, ch:[`endocrine system`,`limbic system`,`central nervous system`,`peripheral nervous system`], ans:3, exp:`The peripheral nervous system (PNS) includes all the nerves branching out from the brain and spinal cord to the rest of the body.` },
      { q:`Sensory neurons primarily function to:`, ch:[`carry information from sensory receptors toward the central nervous system`,`carry signals only within the brain`,`store memories`,`trigger muscle contraction directly`], ans:0, exp:`Sensory (afferent) neurons detect stimuli and transmit that information toward the brain and spinal cord for processing.` },
      { q:`Motor neurons primarily function to:`, ch:[`produce neurotransmitters only in the brain`,`carry signals from the central nervous system to muscles or glands`,`detect light in the retina`,`store long-term memories`], ans:1, exp:`Motor (efferent) neurons carry outgoing signals from the brain and spinal cord to muscles and glands, triggering actions like muscle contraction.` },
      { q:`Why is a reflex, such as pulling your hand away from a hot stove, so fast?`, ch:[`Reflexes are learned behaviors practiced over years`,`It requires no neurons at all`,`The signal travels through a short reflex arc, often bypassing conscious brain processing`,`It only involves the sense of smell`], ans:2, exp:`Many reflexes travel through a short reflex arc involving the spinal cord, allowing a rapid motor response before the signal fully reaches the brain.` },
      { q:`A typical reflex arc, such as the knee-jerk reflex, generally involves signals passing through which pathway?`, ch:[`Only sensory neurons with no motor response`,`Only the brain, with no spinal cord involvement`,`Muscle to muscle directly, with no neurons`,`Sensory receptor, sensory neuron, spinal cord, motor neuron, muscle`], ans:3, exp:`In a reflex arc, a sensory receptor detects a stimulus, a sensory neuron carries the signal to the spinal cord, which relays it via a motor neuron to trigger a rapid muscle response.` },
    ]
  },
  {
    id:`bb125`, cat:`Life Sciences`, title:`The Endocrine System: Hormones 101`, diff:`Easy`,
    qs:[
      { q:`Hormones are best described as:`, ch:[`structural proteins that build muscle tissue`,`enzymes that only work in the digestive tract`,`chemical messengers released into the blood that affect target cells elsewhere`,`electrical signals traveling along nerves`], ans:2, exp:`Hormones are chemical signaling molecules released by endocrine glands directly into the bloodstream, traveling to target cells elsewhere in the body.` },
      { q:`The endocrine system differs from exocrine glands (like sweat glands) because endocrine glands:`, ch:[`only function during childhood`,`do not produce any secretions`,`release their products through ducts onto a surface`,`release hormones directly into the bloodstream, without ducts`], ans:3, exp:`Endocrine glands are "ductless" glands that secrete hormones directly into the bloodstream, unlike exocrine glands, which release products through ducts.` },
      { q:`The pituitary gland is often called the master gland because it:`, ch:[`regulates many other endocrine glands by releasing controlling hormones`,`is located in the abdomen`,`is the largest gland in the body`,`only produces one hormone`], ans:0, exp:`The pituitary gland, at the base of the brain, releases hormones that control the activity of many other endocrine glands, including the thyroid and adrenal glands.` },
      { q:`The thyroid gland primarily regulates:`, ch:[`immune cell production`,`the body's overall metabolic rate`,`blood clotting`,`digestion of fats`], ans:1, exp:`The thyroid gland produces hormones that regulate how quickly cells use energy, influencing metabolism, growth, and body temperature.` },
      { q:`The adrenal glands release adrenaline (epinephrine), which prepares the body for:`, ch:[`digestion after a meal`,`sleep and relaxation`,`the "fight or flight" response during stress`,`long-term bone growth`], ans:2, exp:`Adrenaline is released rapidly in stressful situations, increasing heart rate, blood flow to muscles, and alertness as part of the fight-or-flight response.` },
      { q:`Why does a specific hormone only affect certain target cells and not every cell in the body?`, ch:[`Hormones are destroyed before reaching other cells`,`Target cells are located only in the brain`,`Hormones physically cannot reach most cells`,`Only target cells have the specific receptor proteins that recognize that hormone`], ans:3, exp:`Hormones circulate throughout the bloodstream and reach nearly all cells, but only cells with matching receptor proteins for that hormone will respond.` },
      { q:`Which gland releases growth hormone, which stimulates growth in children and adolescents?`, ch:[`Pituitary gland`,`Pancreas`,`Thyroid gland`,`Adrenal gland`], ans:0, exp:`The pituitary gland secretes growth hormone, which stimulates growth of bones and tissues, particularly important during childhood and adolescence.` },
      { q:`Compared to nervous system signals, hormonal signals generally:`, ch:[`never involve the bloodstream`,`act more slowly but often produce longer-lasting effects`,`travel faster and are shorter-lived`,`only affect a single, very specific cell`], ans:1, exp:`While nerve impulses are fast and brief, hormones travel through the blood, taking longer to reach target cells but often producing longer-lasting effects.` },
      { q:`A negative feedback loop involving hormones typically works by:`, ch:[`hormones having no effect on their own production`,`only occurring during illness`,`the hormone's effect reducing further release of that same hormone`,`the hormone's effect increasing its own release indefinitely`], ans:2, exp:`In negative feedback, rising hormone levels signal the endocrine gland to reduce further hormone release, keeping levels within a stable range.` },
      { q:`Which of these is an endocrine gland that also has an important non-hormonal digestive function?`, ch:[`Pituitary gland`,`Adrenal gland`,`Thyroid gland`,`Pancreas`], ans:3, exp:`The pancreas has both an endocrine role (secreting insulin and glucagon) and an exocrine role (secreting digestive enzymes into the small intestine).` },
      { q:`Which best describes how hormones typically reach their target cells throughout the body?`, ch:[`By traveling through the bloodstream after release from a gland`,`By diffusing through the skin`,`Through direct nerve connections`,`Through the digestive tract only`], ans:0, exp:`Endocrine glands secrete hormones directly into the bloodstream, which carries them throughout the body until they encounter cells with the appropriate receptors.` },
    ]
  },
  {
    id:`bb126`, cat:`Life Sciences`, title:`The Reproductive System Basics`, diff:`Easy`,
    qs:[
      { q:`The male reproductive system produces sperm cells primarily in the:`, ch:[`prostate gland`,`urethra`,`vas deferens`,`testes`], ans:3, exp:`The testes are the primary male reproductive organs where sperm cells are produced, along with the hormone testosterone.` },
      { q:`In the female reproductive system, egg cells (ova) mature and are released from the:`, ch:[`ovaries`,`cervix`,`vagina`,`uterus`], ans:0, exp:`The ovaries store immature egg cells and release one mature egg (ovulation) roughly once per menstrual cycle.` },
      { q:`Fertilization, the fusion of sperm and egg, normally takes place in the:`, ch:[`uterus`,`fallopian tube`,`vagina`,`ovary`], ans:1, exp:`Fertilization typically occurs in the fallopian tube, where a sperm cell can meet and fuse with an egg released from the ovary.` },
      { q:`After fertilization, the resulting single cell is called a:`, ch:[`gamete`,`follicle`,`zygote`,`embryo immediately`], ans:2, exp:`The zygote is the single fertilized cell formed when sperm and egg fuse; it begins dividing repeatedly as it travels to the uterus.` },
      { q:`Where does a fertilized egg typically implant and develop during pregnancy?`, ch:[`The ovary`,`The fallopian tube (for the full pregnancy)`,`The cervix`,`The lining of the uterus`], ans:3, exp:`After fertilization, the developing embryo travels to the uterus and implants in its thickened lining, where it continues developing throughout pregnancy.` },
      { q:`The hormone primarily responsible for triggering male puberty changes, such as increased muscle mass and voice deepening, is:`, ch:[`testosterone`,`insulin`,`thyroxine`,`estrogen`], ans:0, exp:`Testosterone, produced mainly by the testes, drives the development of male secondary sex characteristics during puberty.` },
      { q:`The hormone primarily responsible for regulating the menstrual cycle and female secondary sex characteristics is:`, ch:[`adrenaline`,`estrogen`,`glucagon`,`testosterone`], ans:1, exp:`Estrogen, produced mainly by the ovaries, regulates the menstrual cycle and drives female secondary sex characteristics that develop during puberty.` },
      { q:`Roughly how long is a typical human menstrual cycle?`, ch:[`90 days`,`3 days`,`about 28 days`,`7 days`], ans:2, exp:`A typical menstrual cycle lasts about 28 days on average, though it can normally range from about 21 to 35 days.` },
      { q:`If an egg is not fertilized during a menstrual cycle, what generally happens?`, ch:[`The egg immediately becomes a zygote anyway`,`Ovulation is permanently stopped`,`The ovaries stop functioning`,`The uterine lining sheds, resulting in menstruation`], ans:3, exp:`When fertilization does not occur, hormone levels drop, causing the thickened uterine lining to shed, resulting in menstrual bleeding.` },
      { q:`Roughly how long is a typical full-term human pregnancy (gestation)?`, ch:[`About 40 weeks (about 9 months)`,`About 6 weeks`,`About 18 months`,`About 3 months`], ans:0, exp:`A typical human pregnancy lasts about 40 weeks, or roughly 9 months, counted from the last menstrual period to birth.` },
      { q:`Puberty is best described as:`, ch:[`a stage that only affects emotional development`,`the developmental period when hormones trigger sexual maturation and reproductive capability`,`a process that occurs only in females`,`a disease affecting the reproductive organs`], ans:1, exp:`Puberty is a normal developmental stage, driven by hormones like testosterone and estrogen, during which the body matures and becomes capable of reproduction.` },
    ]
  },
  {
    id:`bb127`, cat:`Life Sciences`, title:`Genetic Disorders: Common Examples & Inheritance`, diff:`Medium`,
    qs:[
      { q:`A person who carries one copy of a recessive disease allele but shows no symptoms is called a:`, ch:[`carrier`,`homozygote`,`mutant`,`phenotype`], ans:0, exp:`A carrier has one recessive allele and one dominant (normal) allele. Because the condition is recessive, the carrier typically shows no symptoms but can pass the allele to offspring.` },
      { q:`Cystic fibrosis and sickle cell anemia are both examples of:`, ch:[`X-linked dominant disorders`,`autosomal recessive disorders`,`disorders caused by an extra chromosome`,`sex-linked recessive disorders`], ans:1, exp:`Both are autosomal recessive disorders, meaning a person must inherit two copies of the mutated allele, one from each parent, to show symptoms.` },
      { q:`Down syndrome is typically caused by:`, ch:[`a single gene mutation on the X chromosome`,`exposure to radiation during childhood`,`having three copies of chromosome 21 instead of two`,`a missing Y chromosome`], ans:2, exp:`Down syndrome most commonly results from trisomy 21, having three copies of chromosome 21 due to a nondisjunction error during egg or sperm formation.` },
      { q:`Red-green color blindness is most commonly inherited as a(n):`, ch:[`autosomal dominant trait`,`trait unrelated to genetics`,`autosomal recessive trait`,`X-linked recessive trait`], ans:3, exp:`The most common form of red-green color blindness is caused by a recessive allele on the X chromosome, occurring much more often in males than females.` },
      { q:`Why are X-linked recessive disorders like color blindness more common in males than females?`, ch:[`Males only have one X chromosome, so a single recessive allele is enough to cause the trait`,`Males have two X chromosomes`,`Females cannot inherit X-linked traits`,`The Y chromosome causes the disorder`], ans:0, exp:`Males (XY) have only one X chromosome, so a single recessive allele on that X is expressed. Females (XX) need two copies to show the trait.` },
      { q:`Huntington's disease is unusual among many well-known genetic disorders because it is:`, ch:[`caused by an extra chromosome`,`inherited as an autosomal dominant trait, so only one copy of the allele causes disease`,`only present in carriers with no symptoms`,`caused entirely by environmental factors`], ans:1, exp:`Huntington's disease follows autosomal dominant inheritance, meaning a single copy of the mutated allele from one parent is enough to eventually cause the disease.` },
      { q:`If two carrier parents (each heterozygous) for a recessive disorder have a child, what is the probability the child will have the disorder?`, ch:[`0%`,`100%`,`25%`,`50%`], ans:2, exp:`For two heterozygous (Aa x Aa) parents, the expected ratio is 1 AA : 2 Aa : 1 aa, giving a 25% chance the child inherits two recessive alleles and shows the disorder.` },
      { q:`A karyotype is a laboratory tool used to:`, ch:[`measure blood glucose levels`,`sequence an individual's entire genome`,`test for infectious diseases`,`visually display and count an individual's chromosomes to detect abnormalities`], ans:3, exp:`A karyotype is an image showing all of a person's chromosomes arranged by size and pairing, allowing detection of abnormalities in chromosome number or structure.` },
      { q:`Nondisjunction is a term describing:`, ch:[`the failure of chromosomes to separate properly during cell division`,`a mutation in a single DNA base pair`,`the normal separation of chromosomes`,`the process of DNA replication`], ans:0, exp:`Nondisjunction occurs when chromosome pairs fail to separate properly during meiosis, resulting in gametes with an abnormal chromosome number, as in Down syndrome.` },
      { q:`Sickle cell trait (being a carrier for sickle cell anemia) can actually provide some protection against:`, ch:[`the common cold`,`malaria`,`type 1 diabetes`,`seasonal allergies`], ans:1, exp:`Carriers of the sickle cell allele have some resistance to malaria, since the parasite has difficulty surviving in red blood cells carrying even one copy of the sickle allele.` },
      { q:`Genetic counselors often use family history and Punnett squares to help families understand:`, ch:[`how to treat infections`,`nutrition requirements`,`the likelihood of passing on an inherited genetic disorder`,`how to perform surgery`], ans:2, exp:`Genetic counselors analyze inheritance patterns and family history, often using Punnett squares, to estimate the probability a couple's children might inherit a genetic condition.` },
    ]
  },
  {
    id:`bb128`, cat:`Life Sciences`, title:`Evolution Evidence: Fossils, Homology & Biogeography`, diff:`Medium`,
    qs:[
      { q:`Fossils provide evidence for evolution primarily by:`, ch:[`demonstrating that species never change`,`showing a record of how species have changed over long periods of time`,`proving exactly how old the Earth is`,`showing that all species appeared at the same time`], ans:1, exp:`The fossil record shows a chronological sequence of organisms, revealing gradual changes in body forms over millions of years.` },
      { q:`Homologous structures, such as the forelimbs of humans, whales, and bats, are similar in underlying bone structure because:`, ch:[`they have no evolutionary explanation`,`they evolved completely independently for the same function`,`they were inherited from a common ancestor, even though they may look and function differently now`,`they are identical in every species`], ans:2, exp:`Homologous structures share underlying anatomy inherited from a shared ancestor, even though they have been modified for different functions.` },
      { q:`Analogous structures, such as the wings of insects and birds, are similar in function but arose through:`, ch:[`vestigial development`,`inheritance from a recent common ancestor`,`identical genetic mutations`,`convergent evolution, evolving independently in unrelated lineages`], ans:3, exp:`Analogous structures evolved independently in unrelated species facing similar environmental pressures, a pattern called convergent evolution, not shared ancestry.` },
      { q:`The human appendix and tailbone are often cited as examples of:`, ch:[`vestigial structures, reduced remnants of features that were more functional in ancestors`,`homologous structures shared with all mammals equally`,`analogous structures`,`transitional fossils`], ans:0, exp:`Vestigial structures are reduced or non-functional remnants of features that served a purpose in ancestral species but have lost most of their function over time.` },
      { q:`Biogeography, the study of species' geographic distribution, supports evolution by showing that:`, ch:[`islands never have unique species`,`closely related species are often found on the same or nearby landmasses, reflecting shared ancestry`,`all species are distributed randomly around the globe`,`species distributions never relate to geological history`], ans:1, exp:`Biogeography reveals patterns, such as related species clustering on the same continent, consistent with species evolving from a common ancestor and spreading over time.` },
      { q:`Darwin's finches on the Galapagos Islands are a classic example used to illustrate:`, ch:[`fossil dating techniques`,`vestigial structures`,`how a single ancestral species can diversify into multiple species with different beak shapes suited to different food sources`,`analogous structures in unrelated animals`], ans:2, exp:`Finches on different Galapagos islands had beak shapes suited to their local food sources, suggesting descent from a common ancestor with diversification through natural selection.` },
      { q:`Comparative embryology provides evolutionary evidence by showing that:`, ch:[`embryos provide no useful scientific information`,`all animal embryos are visually identical throughout development`,`embryos develop completely differently depending on adult body plan`,`distantly related vertebrate embryos (such as fish, chickens, and humans) show striking similarities in early development`], ans:3, exp:`Early-stage embryos of many vertebrate species share strikingly similar features, suggesting these species share common evolutionary ancestry despite looking very different as adults.` },
      { q:`A "transitional fossil" is best described as one that:`, ch:[`shows a mix of features from an ancestral group and a descendant group, such as Tiktaalik between fish and early tetrapods`,`is always the very first fossil of its kind ever formed`,`shows no relationship to modern species`,`can never be dated accurately`], ans:0, exp:`Transitional fossils display a combination of traits from both an older and more derived group, illustrating gradual evolutionary steps between major groups.` },
      { q:`Comparing DNA sequences between species provides evidence for evolution because:`, ch:[`DNA comparison cannot reveal evolutionary relationships`,`species that are more closely related generally show more similar DNA sequences`,`all species have identical DNA`,`DNA differences are always caused by radiation`], ans:1, exp:`The degree of similarity between DNA sequences generally correlates with how recently species shared a common ancestor, providing molecular evidence for evolutionary relationships.` },
      { q:`Which of the following is the best example of an analogous structure pair?`, ch:[`Bird wing and bat wing`,`Human arm and cat leg`,`Dolphin flipper (mammal) and shark fin (fish), which look similar but evolved independently for swimming`,`Human arm and whale flipper`], ans:2, exp:`Dolphins and sharks are not closely related, but both evolved similar fin-like structures for swimming through convergent evolution, a classic analogous structure example.` },
      { q:`Why are marsupials (like kangaroos) especially diverse in Australia compared to the rest of the world?`, ch:[`Placental mammals evolved first only in Australia`,`Marsupials cannot survive on other continents at all`,`Marsupials were introduced to Australia by humans recently`,`Australia separated from other landmasses early, allowing marsupials to evolve and diversify in relative isolation`], ans:3, exp:`Australia separated from other continents millions of years ago, isolating marsupial populations, which then diversified extensively with limited competition from placental mammals.` },
    ]
  },
  {
    id:`bb129`, cat:`Life Sciences`, title:`Natural Selection in Action: Real-World Case Studies`, diff:`Medium`,
    qs:[
      { q:`Natural selection requires which of the following to occur within a population?`, ch:[`No environmental pressures of any kind`,`All individuals reproducing at exactly the same rate`,`Heritable variation among individuals`,`Every individual must be genetically identical`], ans:2, exp:`Natural selection acts on existing heritable variation; without differences that can be passed to offspring, there would be no traits for selection to act upon.` },
      { q:`In the classic peppered moth example in industrial England, dark-colored moths became more common after pollution darkened tree bark because:`, ch:[`light moths migrated away entirely`,`dark moths reproduced faster regardless of camouflage`,`pollution directly changed the moths' color`,`dark moths were better camouflaged from predators against sooty bark and survived more often`], ans:3, exp:`As pollution darkened tree trunks, dark-colored moths were better camouflaged from bird predators, so they survived and reproduced more, increasing the dark allele's frequency.` },
      { q:`The evolution of antibiotic-resistant bacteria is a modern example of natural selection because:`, ch:[`bacteria with pre-existing resistance mutations survive antibiotic treatment and reproduce, passing resistance to offspring`,`all bacteria are equally affected by antibiotics`,`antibiotics create resistance genes from scratch`,`bacteria intentionally develop resistance to survive`], ans:0, exp:`A few bacteria may already carry resistance mutations. Antibiotic use kills susceptible bacteria, leaving resistant ones to survive and multiply, increasing resistance over generations.` },
      { q:`In evolutionary biology, "fitness" refers to:`, ch:[`how long an individual organism lives`,`an organism's relative ability to survive and pass on its genes to the next generation`,`an organism's physical strength`,`how fast an organism can run`], ans:1, exp:`Fitness in an evolutionary sense measures reproductive success, how effectively an individual's genes are represented in the next generation, not physical strength.` },
      { q:`Researchers studying Galapagos finches observed that after a severe drought reduced small, soft seeds, average beak depth in the population increased over subsequent generations because:`, ch:[`birds with shallow beaks migrated to a different island`,`beak depth is unrelated to seed availability`,`birds with deeper, stronger beaks could crack the remaining large, hard seeds and survived better`,`all finches developed deeper beaks during their lifetimes in response to the drought`], ans:2, exp:`During drought, only large, hard seeds remained, favoring finches with deeper, stronger beaks, whose offspring inherited that beak-depth advantage; this was documented by the Grants' research.` },
      { q:`A "selective pressure" in natural selection refers to:`, ch:[`the process of DNA replication`,`a structure used only by plants`,`a type of genetic mutation`,`any environmental factor that affects which individuals are more likely to survive and reproduce`], ans:3, exp:`Selective pressures are environmental factors, such as predators, disease, or food scarcity, that make certain heritable traits more or less advantageous for survival and reproduction.` },
      { q:`Pesticide resistance in insect populations tends to develop because:`, ch:[`a few insects with natural resistance survive pesticide application and pass that trait to their offspring`,`pesticides have no effect on insect populations`,`pesticides cause insects to mutate on purpose to survive`,`insects can learn to avoid pesticides during their lifetime`], ans:0, exp:`When pesticides are applied, most susceptible insects die, but individuals with a resistance mutation survive and reproduce, increasing resistant insects in the population over generations.` },
      { q:`Which statement correctly distinguishes natural selection from simple genetic mutation?`, ch:[`Natural selection only happens in laboratory settings`,`Mutation creates new genetic variation, while natural selection acts on that variation by favoring traits that improve survival and reproduction`,`Mutation and natural selection are the exact same process`,`Selection creates new mutations directly`], ans:1, exp:`Mutations are random changes introducing new genetic variation; natural selection is the non-random process favoring certain variants based on their effect on survival and reproduction.` },
      { q:`Why can bacteria evolve antibiotic resistance relatively quickly compared to larger animals evolving new traits?`, ch:[`Bacteria have no DNA`,`Antibiotics cause all bacteria to mutate identically`,`Bacteria reproduce extremely rapidly, producing many generations (and chances for beneficial mutations to spread) in a short time`,`Bacteria do not follow the rules of natural selection`], ans:2, exp:`Because bacteria can reproduce every 20-30 minutes under ideal conditions, populations go through many generations quickly, giving natural selection far more opportunities to act.` },
      { q:`If a population of insects becomes resistant to a pesticide, and the pesticide is then discontinued, resistance levels might decline over time if:`, ch:[`insects instantly lose all their DNA`,`natural selection stops working once resistance appears`,`resistance is completely permanent and can never change`,`maintaining resistance genes has some cost to fitness when the pesticide is no longer present, so non-resistant insects have an advantage again`], ans:3, exp:`Resistance traits sometimes carry a fitness cost; without the pesticide's selective pressure, non-resistant individuals may be at a slight advantage, causing resistance frequency to decline.` },
      { q:`Which best summarizes the overall lesson from these natural selection case studies?`, ch:[`Environmental changes can measurably shift trait frequencies in a population within just a few generations`,`Natural selection only applies to insects and bacteria`,`Evolution only occurs over millions of years and can never be observed directly`,`Organisms choose to evolve traits they need`], ans:0, exp:`Case studies like peppered moths, antibiotic resistance, and finch beak size show natural selection can produce observable, measurable shifts in trait frequency within relatively short timeframes.` },
    ]
  },
  {
    id:`bb130`, cat:`Life Sciences`, title:`Symbiosis & Species Interactions`, diff:`Easy`,
    qs:[
      { q:`A symbiotic relationship in which both species benefit is called:`, ch:[`parasitism`,`predation`,`competition`,`mutualism`], ans:3, exp:`Mutualism describes a close, long-term relationship between two species in which both partners benefit, such as bees pollinating flowers while gaining nectar.` },
      { q:`A relationship in which one species benefits and the other is harmed is called:`, ch:[`parasitism`,`mutualism`,`predation only`,`commensalism`], ans:0, exp:`Parasitism is a relationship where one organism benefits at the expense of the other, often without immediately killing it, such as a tapeworm in an intestine.` },
      { q:`A relationship in which one species benefits and the other is neither helped nor harmed is called:`, ch:[`parasitism`,`commensalism`,`predation`,`mutualism`], ans:1, exp:`Commensalism describes a relationship where one species benefits while the other is largely unaffected, such as barnacles attaching to a whale for transport.` },
      { q:`The relationship between clownfish and sea anemones, where the clownfish gains protection and the anemone gets food scraps and cleaning, is an example of:`, ch:[`predation`,`competition`,`mutualism`,`parasitism`], ans:2, exp:`Both benefit: the anemone's tentacles protect the clownfish, while the clownfish helps clean the anemone and drives away some predators.` },
      { q:`Predation is best defined as:`, ch:[`two species sharing the same limited resource`,`one organism living harmlessly on another`,`a relationship benefiting both species equally`,`an interaction where one organism (predator) kills and consumes another (prey)`], ans:3, exp:`Predation involves a predator hunting, killing, and consuming a prey organism, directly affecting the population sizes of both species over time.` },
      { q:`When two species rely on the same limited resource, such as two bird species competing for the same nesting sites, this interaction is called:`, ch:[`competition`,`commensalism`,`parasitism`,`mutualism`], ans:0, exp:`Competition occurs when species require the same limited resource, such as food, water, or space, potentially reducing the survival or reproduction of both.` },
      { q:`A tick feeding on a deer's blood, gaining nourishment while potentially weakening the deer, is an example of:`, ch:[`commensalism`,`parasitism`,`predation`,`mutualism`], ans:1, exp:`The tick benefits by obtaining a blood meal while the deer is harmed through blood loss and potential disease transmission, a classic example of parasitism.` },
      { q:`Lichens, often found growing on rocks and trees, are formed by a mutualistic relationship between:`, ch:[`a plant and an insect`,`a bacterium and a virus`,`a fungus and an alga (or cyanobacterium)`,`two species of animals`], ans:2, exp:`A lichen is a mutualistic partnership between a fungus, which provides structure, and a photosynthetic alga or cyanobacterium, which provides food.` },
      { q:`Oxpecker birds that eat ticks and parasites off the skin of large mammals like rhinos illustrate:`, ch:[`predation, since the rhino is killed`,`competition for food between the two species`,`a relationship with no interaction at all`,`mutualism, since both species can benefit from this interaction`], ans:3, exp:`Oxpeckers get a meal of ticks and parasites, while the host mammal is potentially relieved of pests, a commonly cited example of mutualism.` },
      { q:`If two plant species in the same area both need direct sunlight and one grows taller, shading out the other, this best illustrates:`, ch:[`competition for a limited resource (light)`,`parasitism`,`commensalism`,`mutualism`], ans:0, exp:`Both species require the same limited resource (sunlight), and one outcompeting the other for it is a clear example of interspecies competition.` },
      { q:`A remora fish attaching to a shark to feed on scraps of the shark's food, without helping or harming the shark, best illustrates:`, ch:[`parasitism`,`commensalism`,`predation`,`mutualism`], ans:1, exp:`The remora benefits by getting an easy meal and transportation, while the shark is generally unaffected, a classic textbook example of commensalism.` },
    ]
  },
  {
    id:`bb131`, cat:`Life Sciences`, title:`Food Chains, Food Webs & Trophic Levels`, diff:`Easy`,
    qs:[
      { q:`Organisms that produce their own food through photosynthesis, such as plants and algae, are called:`, ch:[`producers`,`primary consumers`,`decomposers`,`secondary consumers`], ans:0, exp:`Producers, or autotrophs, use sunlight to create their own food through photosynthesis, forming the base of nearly all food chains.` },
      { q:`An organism that eats producers directly, such as a rabbit eating grass, is called a:`, ch:[`decomposer`,`primary consumer`,`tertiary consumer`,`secondary consumer`], ans:1, exp:`Primary consumers are herbivores that feed directly on producers, occupying the second trophic level in a food chain.` },
      { q:`An organism that eats primary consumers, such as a fox eating a rabbit, is called a:`, ch:[`producer`,`decomposer`,`secondary consumer`,`primary consumer`], ans:2, exp:`Secondary consumers are typically carnivores or omnivores that eat primary consumers, occupying the third trophic level in a food chain.` },
      { q:`Organisms such as fungi and bacteria that break down dead organisms and waste, recycling nutrients back into the ecosystem, are called:`, ch:[`producers`,`primary consumers`,`apex predators`,`decomposers`], ans:3, exp:`Decomposers break down dead plant and animal matter into simpler substances, returning nutrients like nitrogen and carbon to the soil.` },
      { q:`A food web differs from a single food chain because a food web:`, ch:[`shows multiple interconnected feeding relationships among many species in an ecosystem`,`only shows one possible path of energy flow`,`only includes producers`,`never includes decomposers`], ans:0, exp:`While a food chain shows one linear feeding sequence, a food web shows the many interconnected food chains within an ecosystem.` },
      { q:`According to the general "10% rule" in ecology, when energy is transferred from one trophic level to the next:`, ch:[`all of the energy is transferred with none lost`,`only about 10% of the energy is passed on, with the rest lost mostly as heat`,`the amount of energy transferred always doubles`,`no energy is available for the next level`], ans:1, exp:`On average, only about 10% of the energy stored in one trophic level is available to the next level; the rest is lost as metabolic heat or used for life processes.` },
      { q:`Because of the 10% energy transfer rule, ecological pyramids of biomass and energy are typically:`, ch:[`upside down, with the fewest producers at the base`,`rectangular, with equal amounts at every level`,`widest at the base (producers) and narrower at each higher trophic level`,`impossible to construct accurately`], ans:2, exp:`Since energy decreases substantially at each trophic level, ecological pyramids are widest at the producer base and progressively narrower toward top predators.` },
      { q:`An "apex predator," such as a great white shark or a lion, is best described as an organism that:`, ch:[`only eats producers`,`is eaten by many other species`,`occupies the lowest trophic level`,`sits at the top of its food chain with few or no natural predators`], ans:3, exp:`Apex predators occupy the highest trophic level in their ecosystem and typically have no natural predators of their own as adults.` },
      { q:`Why is there usually a much smaller number and total biomass of top predators compared to producers in an ecosystem?`, ch:[`Energy is lost at each trophic level, so less energy is available to support organisms higher up the food chain`,`Predators reproduce much more slowly regardless of energy`,`Producers actively avoid being eaten`,`There is no real relationship between trophic level and population size`], ans:0, exp:`Because roughly 90% of energy is lost as it moves up each trophic level, far less total energy is available to support organisms at higher trophic levels.` },
      { q:`In the food chain: grass, grasshopper, frog, snake, hawk, which organism is the tertiary consumer?`, ch:[`grasshopper`,`snake`,`grass`,`hawk`], ans:1, exp:`Grass is the producer, the grasshopper is the primary consumer, the frog is the secondary consumer, and the snake, eating the frog, is the tertiary consumer.` },
      { q:`Removing a keystone or apex predator species from an ecosystem often leads to:`, ch:[`no noticeable changes to the ecosystem`,`producers disappearing immediately`,`overpopulation of prey species and cascading effects throughout the food web`,`an immediate increase in decomposer numbers only`], ans:2, exp:`Removing a top predator can allow prey populations to grow unchecked, over-consuming producers and disrupting the balance of the entire food web, known as a trophic cascade.` },
    ]
  },
  {
    id:`bb132`, cat:`Life Sciences`, title:`Biomes of the World`, diff:`Easy`,
    qs:[
      { q:`A biome is best defined as:`, ch:[`a region defined solely by its animal species, ignoring climate`,`a large geographic region characterized by a distinctive climate and community of plants and animals`,`a single individual ecosystem the size of a pond`,`any area with high biodiversity only`], ans:1, exp:`A biome is a large-scale ecological region defined mainly by its climate, which shapes the characteristic plant and animal communities found there.` },
      { q:`The tropical rainforest biome is characterized by:`, ch:[`extremely low temperatures and permafrost`,`very low rainfall and sparse vegetation`,`high rainfall, warm temperatures year-round, and the greatest biodiversity of any biome`,`long, cold winters and short summers`], ans:2, exp:`Tropical rainforests receive abundant rainfall and stay warm year-round, supporting an extraordinary diversity of plant and animal species.` },
      { q:`Deserts are primarily defined by:`, ch:[`year-round high humidity`,`consistently freezing temperatures`,`dense forest cover`,`very low annual precipitation, regardless of temperature`], ans:3, exp:`Deserts are classified based on low precipitation, not temperature alone; some deserts are hot, while others, like parts of Antarctica, are cold.` },
      { q:`The tundra biome, found near the poles, is characterized by:`, ch:[`extremely cold temperatures, low precipitation, and a permanently frozen subsoil layer called permafrost`,`tall trees and warm summers`,`abundant rainfall year-round`,`dense tropical vegetation`], ans:0, exp:`Tundra ecosystems have very cold temperatures, short growing seasons, and permafrost, which limits root growth and prevents large trees from growing.` },
      { q:`The taiga (boreal forest) biome is dominated by which type of vegetation?`, ch:[`Short grasses with almost no trees`,`Coniferous (needle-leaved) evergreen trees like spruce and fir`,`Cacti and succulent plants`,`Tropical broadleaf trees`], ans:1, exp:`The taiga, the largest land biome, is dominated by cold-tolerant coniferous evergreen trees such as spruce, fir, and pine.` },
      { q:`Grassland (or savanna) biomes typically have:`, ch:[`no herbivore populations`,`dense forest canopy blocking most sunlight`,`moderate rainfall, insufficient to support large forests, favoring grasses over trees`,`permafrost and extremely cold winters`], ans:2, exp:`Grasslands receive enough rainfall to support grasses but not usually enough to sustain large forests, resulting in landscapes dominated by grasses.` },
      { q:`Which adaptation would most likely help a desert plant, like a cactus, survive its environment?`, ch:[`Blooming only during the coldest months`,`Large, thin leaves to maximize water loss`,`Shallow, wide-spreading roots that avoid absorbing water`,`Thick, water-storing stems and small spines instead of leaves to reduce water loss`], ans:3, exp:`Desert plants like cacti often have thick, fleshy stems that store water and small spines that greatly reduce water loss through transpiration compared to broad leaves.` },
      { q:`Temperate deciduous forests, found in regions like the eastern United States, are distinguished by:`, ch:[`trees that lose their leaves seasonally, along with moderate rainfall and four distinct seasons`,`no seasonal changes throughout the year`,`year-round tropical warmth`,`permafrost soil`], ans:0, exp:`Temperate deciduous forests experience four distinct seasons; their broadleaf trees, such as oak and maple, lose their leaves each autumn to conserve resources during winter.` },
      { q:`Which biome generally has the LOWEST biodiversity, largely due to extreme cold and a short growing season?`, ch:[`Savanna`,`Tundra`,`Tropical rainforest`,`Temperate deciduous forest`], ans:1, exp:`The tundra's harsh conditions limit the variety of species that can survive there, giving it much lower biodiversity than warmer, wetter biomes like rainforests.` },
      { q:`The two main factors used to classify terrestrial biomes are:`, ch:[`distance from the ocean only`,`soil color and elevation only`,`temperature and precipitation (average and seasonal patterns)`,`number of predator species and prey species`], ans:2, exp:`Terrestrial biomes are primarily classified based on average temperature and precipitation, since these factors most strongly determine which organisms can survive there.` },
      { q:`Which biome would you most expect to find large migratory herds of grazing animals, such as wildebeest, along with scattered trees?`, ch:[`Tropical rainforest`,`Tundra`,`Taiga`,`Savanna`], ans:3, exp:`The African savanna, a tropical grassland with scattered trees and a distinct wet/dry season, supports large herds of grazing herbivores like wildebeest and zebra.` },
    ]
  },
  {
    id:`bb133`, cat:`Life Sciences`, title:`Human Nutrition: Reading a Nutrition Label`, diff:`Easy`,
    qs:[
      { q:`On a nutrition facts label, the "serving size" tells you:`, ch:[`the recommended daily calorie intake for everyone`,`the exact number of servings you must eat per day`,`the amount of food the nutrition information is based on, not necessarily how much you should eat`,`the total calories in the entire package`], ans:2, exp:`Serving size indicates the specific portion that all listed nutrient amounts are based on; if you eat more or less, you need to adjust the numbers accordingly.` },
      { q:`Which of the following is one of the three main macronutrients that provide the body with calories (energy)?`, ch:[`Calcium`,`Iron`,`Vitamin C`,`Carbohydrates`], ans:3, exp:`Carbohydrates, along with protein and fat, are macronutrients needed in relatively large amounts that directly provide calories; vitamins and minerals are micronutrients.` },
      { q:`On average, which macronutrient provides the most calories per gram?`, ch:[`Fat (about 9 calories/gram)`,`Water (0 calories/gram)`,`Carbohydrates (about 4 calories/gram)`,`Protein (about 4 calories/gram)`], ans:0, exp:`Fat provides about 9 calories per gram, more than double the roughly 4 calories per gram provided by carbohydrates or protein.` },
      { q:`The "% Daily Value" (%DV) on a nutrition label indicates:`, ch:[`the price of the item relative to nutritional content`,`how much a nutrient in one serving contributes to a total daily diet, based on a 2,000-calorie reference diet`,`the exact number of calories in the food`,`how many grams of that nutrient are in a whole package`], ans:1, exp:`%DV shows the percentage of a recommended daily amount of a nutrient one serving provides, based on a standard 2,000-calorie diet.` },
      { q:`Dietary fiber, listed under carbohydrates on a nutrition label, is important because it:`, ch:[`is a type of added sugar`,`is chemically identical to protein`,`aids digestion and helps you feel full, even though it isn't fully digested by the body`,`provides more calories per gram than fat`], ans:2, exp:`Fiber is a carbohydrate the body cannot fully break down; it aids digestive health and promotes fullness, even though it contributes little usable energy.` },
      { q:`Which type of fat, when consumed in excess, is most strongly linked to increased risk of heart disease?`, ch:[`Polyunsaturated fat`,`Omega-3 fatty acids`,`Monounsaturated fat`,`Saturated fat`], ans:3, exp:`Diets high in saturated fat are associated with higher LDL cholesterol levels and increased cardiovascular disease risk compared to unsaturated fats.` },
      { q:`The difference between "total sugars" and "added sugars" on a nutrition label is that added sugars:`, ch:[`are sugars and syrups added during food processing, separate from sugars naturally present`,`are not required to be listed on labels`,`always appear as a smaller number than total sugars, which is impossible`,`refer only to sugars naturally found in fruit`], ans:0, exp:`Total sugars include naturally occurring and added sugars; added sugars refer specifically to sugars or syrups mixed in during processing, listed separately to track added sweeteners.` },
      { q:`Why might a nutrition label list high sodium content as a health concern for many people?`, ch:[`Sodium always causes weight gain directly`,`Excess sodium intake is linked to high blood pressure in many individuals`,`Sodium has no known health effects`,`Sodium is a type of protein`], ans:1, exp:`Consuming too much sodium over time is associated with increased blood pressure in many people, raising the risk of heart disease and stroke.` },
      { q:`Protein listed on a nutrition label is especially important for the body because it:`, ch:[`cannot be found in plant-based foods`,`is only necessary for infants`,`is used to build and repair tissues such as muscle`,`is the body's preferred and most efficient source of quick energy`], ans:2, exp:`Protein provides amino acids the body uses to build and repair tissues, including muscle, skin, and enzymes, essential at every stage of life.` },
      { q:`Vitamins and minerals shown on a nutrition label (such as Vitamin D, calcium, iron, and potassium) are classified as:`, ch:[`substances with no biological function`,`types of fat`,`macronutrients needed in large amounts`,`micronutrients, needed in smaller amounts but still essential for health`], ans:3, exp:`Vitamins and minerals are micronutrients because the body needs them in much smaller quantities than macronutrients, yet they remain essential for many functions.` },
      { q:`If a food label shows a %DV of 5% or less for a nutrient like saturated fat, this is generally considered:`, ch:[`a low amount of that nutrient in the serving`,`always dangerous regardless of the nutrient`,`an extremely high amount`,`an amount with no defined meaning`], ans:0, exp:`As a general guideline, a %DV of 5% or less is considered low for a nutrient, while 20% or more is considered high.` },
    ]
  },
  {
    id:`bb134`, cat:`Life Sciences`, title:`The Immune System: First & Second Responders`, diff:`Medium`,
    qs:[
      { q:`The skin serves as the body's first line of defense against pathogens primarily by:`, ch:[`producing antibodies directly`,`digesting invading bacteria with stomach acid`,`triggering a fever`,`acting as a physical barrier that prevents most germs from entering the body`], ans:3, exp:`Skin is a tough physical barrier that most pathogens cannot cross, along with mucous membranes, forming the innate immune system's first line of defense.` },
      { q:`Mucus and tears help protect the body from infection partly because they contain:`, ch:[`lysozyme, an enzyme that can break down bacterial cell walls`,`hemoglobin`,`melanin`,`glucose that starves bacteria`], ans:0, exp:`Tears, saliva, and mucus contain lysozyme, an enzyme that helps destroy the cell walls of many bacteria, providing a chemical barrier.` },
      { q:`White blood cells called phagocytes protect the body mainly by:`, ch:[`building new skin cells`,`engulfing and digesting invading pathogens`,`transporting oxygen throughout the blood`,`producing hormones`], ans:1, exp:`Phagocytes, such as macrophages and neutrophils, are white blood cells that engulf and break down bacteria, viruses, and cellular debris.` },
      { q:`Inflammation, marked by redness, heat, swelling, and pain at an injury or infection site, occurs because:`, ch:[`the immune system is malfunctioning`,`nerve cells are permanently damaged`,`blood vessels widen and become more permeable, bringing more immune cells and fluid to fight infection`,`blood flow to the area decreases sharply`], ans:2, exp:`Inflammation is a protective response in which nearby blood vessels dilate and become leakier, increasing blood flow and allowing immune cells and fluid to reach affected tissue.` },
      { q:`A fever helps the body fight infection because:`, ch:[`fever destroys all of the body's own cells`,`fever lowers the metabolic rate to conserve energy`,`fever has no actual immune benefit`,`higher body temperature can slow the growth of many pathogens and enhance immune cell activity`], ans:3, exp:`A moderate fever raises body temperature, which can inhibit reproduction of many bacteria and viruses while also speeding up certain immune responses.` },
      { q:`The lymphatic system supports immune function partly by:`, ch:[`filtering lymph fluid through lymph nodes, where immune cells can detect and respond to pathogens`,`producing digestive enzymes`,`regulating blood sugar levels`,`pumping oxygenated blood throughout the body`], ans:0, exp:`Lymph nodes filter lymph fluid, and their concentrations of immune cells monitor it for pathogens, which is why lymph nodes often swell during infection.` },
      { q:`The body's rapid, general (nonspecific) defenses, such as physical barriers, phagocytes, and inflammation, are collectively part of the:`, ch:[`circulatory system`,`innate immune response, which reacts quickly but the same way to many different pathogens`,`endocrine system`,`adaptive immune response only`], ans:1, exp:`The innate immune system provides fast, general protection against a wide range of pathogens without needing to first recognize a specific germ.` },
      { q:`Specialized proteins called antibodies help fight infection by:`, ch:[`replacing damaged DNA`,`regulating heart rate`,`binding specifically to a particular pathogen, marking it for destruction or blocking its ability to infect cells`,`directly digesting all body cells`], ans:2, exp:`Antibodies recognize and bind to specific molecules on a pathogen's surface, either neutralizing it directly or flagging it for destruction by other immune cells.` },
      { q:`After successfully fighting off a specific infection, the body often retains "memory cells," which allow it to:`, ch:[`become immune to all future infections of any kind`,`lose all prior immune function`,`produce fewer white blood cells overall`,`respond faster and more effectively if the same pathogen is encountered again in the future`], ans:3, exp:`Memory cells are long-lived immune cells that remember a specific pathogen, allowing a much faster and stronger response if that pathogen is encountered again.` },
      { q:`Compared to the fast-acting innate response, the second line of defense involving memory and highly specific antibody production is called:`, ch:[`the adaptive (specific) immune response, which typically takes longer to activate the first time`,`the reflex response`,`the endocrine response`,`the digestive response`], ans:0, exp:`The adaptive immune response targets specific pathogens using specialized cells and antibodies; it usually takes several days to activate the first time but responds much faster later.` },
      { q:`Why do lymph nodes near an infection site often become swollen and tender?`, ch:[`They are shrinking due to cell death`,`Immune cells are actively multiplying and responding to trapped pathogens within the node`,`They are being damaged by the infection directly`,`They are filling with excess blood only`], ans:1, exp:`When pathogens are filtered into a lymph node, immune cells there rapidly multiply and become more active, causing the node to swell and often feel tender.` },
    ]
  },
  {
    id:`bb135`, cat:`Life Sciences`, title:`Genetically Modified Organisms (GMOs) & Biotechnology Basics`, diff:`Medium`,
    qs:[
      { q:`A genetically modified organism (GMO) is an organism whose genetic material has been altered using biotechnology to:`, ch:[`introduce or change specific traits that would be difficult to achieve through traditional breeding alone`,`immediately create a brand new species with no relation to the original`,`remove all of its original DNA`,`make it impossible to reproduce`], ans:0, exp:`GMOs have had their DNA directly modified, often by inserting a gene from another organism, to introduce desirable traits more precisely and quickly than traditional breeding.` },
      { q:`How does genetic modification differ from traditional selective breeding?`, ch:[`Selective breeding is a modern laboratory technique invented in the last decade`,`Genetic modification can directly insert specific genes (sometimes from unrelated species), while selective breeding relies on choosing and crossbreeding organisms with desired traits over generations`,`Genetic modification and selective breeding are exactly the same process`,`Selective breeding always produces GMOs`], ans:1, exp:`Selective breeding gradually favors desired traits by choosing which organisms reproduce, while genetic modification uses lab techniques to directly insert or edit specific genes.` },
      { q:`"Bt corn" is a well-known GMO crop that has been modified to:`, ch:[`grow without any sunlight`,`taste sweeter than regular corn`,`produce a natural protein toxic to certain insect pests, reducing the need for chemical pesticides`,`survive in salt water`], ans:2, exp:`Bt corn contains a gene from the bacterium Bacillus thuringiensis, letting the plant produce a protein toxic to specific insect pests, reducing the need for chemical pesticide use.` },
      { q:`"Golden rice" was genetically engineered to address which nutritional problem, especially in developing regions?`, ch:[`Protein deficiency`,`Excess sugar consumption`,`Calcium deficiency`,`Vitamin A deficiency, by adding genes that let the rice produce beta-carotene`], ans:3, exp:`Golden rice was engineered to produce beta-carotene, which the body converts to vitamin A, aiming to reduce vitamin A deficiency in regions where rice is a dietary staple.` },
      { q:`Before genetic engineering, insulin for diabetes treatment had to be extracted from animal pancreases. Today, most insulin is produced by:`, ch:[`bacteria that have been genetically modified to carry the human insulin gene`,`extracting it from plant seeds`,`synthesizing it entirely from sugar with no biological organisms involved`,`harvesting it from human blood donors`], ans:0, exp:`Scientists inserted the human insulin gene into bacteria, turning them into living factories that produce human insulin in large quantities, safer and more scalable than animal-derived insulin.` },
      { q:`One commonly cited potential benefit of GM crops is that they can:`, ch:[`always eliminate the need for any farming at all`,`be engineered for traits like drought tolerance or pest resistance, potentially increasing crop yields`,`grow without any soil or water`,`never require any regulatory testing`], ans:1, exp:`GM crops can be engineered for traits such as pest resistance or drought tolerance, which supporters argue can help increase yields and food security in challenging conditions.` },
      { q:`A commonly raised concern from critics of GMOs involves:`, ch:[`GMOs being proven to directly cause disease in humans, according to major scientific consensus`,`GMOs having no economic impact on farmers`,`potential effects on biodiversity, such as engineered genes spreading to wild plant populations`,`GMOs being illegal to grow in every country`], ans:2, exp:`A common concern is gene flow, the possibility that genes from GM crops could spread to wild or non-GM relatives through cross-pollination, potentially affecting biodiversity.` },
      { q:`According to major scientific and health organizations, current approved GM foods on the market are generally considered:`, ch:[`more dangerous to eat than any non-GM food`,`untested and unregulated`,`banned worldwide`,`as safe to eat as their conventional counterparts, based on extensive research and regulatory review`], ans:3, exp:`Major scientific bodies, including the WHO and the National Academies of Sciences, generally conclude that approved GM foods currently on the market are as safe to eat as their non-GM counterparts.` },
      { q:`Biotechnology, broadly defined, refers to:`, ch:[`using living organisms or biological systems to develop products or technologies`,`only the study of computer software`,`the study of rocks and minerals`,`a branch of physics focused on particles`], ans:0, exp:`Biotechnology is a broad field that uses living organisms, cells, or biological molecules to develop useful products, ranging from fermenting yogurt to genetically engineering crops.` },
      { q:`Which of the following is an example of biotechnology that predates modern genetic engineering by thousands of years?`, ch:[`Inserting jellyfish genes into mice`,`Using yeast to ferment grains into bread and beer`,`CRISPR gene editing`,`Producing insulin in genetically modified bacteria`], ans:1, exp:`Humans have used biotechnology for thousands of years, such as using yeast to ferment sugars in bread-making and brewing, long before modern genetic engineering tools existed.` },
      { q:`In many countries, foods containing GMO ingredients are subject to:`, ch:[`no rules or regulations of any kind`,`an outright ban on sale`,`government safety review and, in many regions, specific labeling requirements`,`unlimited and unrestricted sale with no testing`], ans:2, exp:`Most countries permitting GMO crops require safety assessments by regulatory agencies before approval, and many regions also require GMO ingredients to be labeled.` },
    ]
  },
  {
    id:`bb136`, cat:`Life Sciences`, title:`Stem Cells 101`, diff:`Medium`,
    qs:[
      { q:`A stem cell is best defined as an unspecialized cell that can:`, ch:[`only be found in plants`,`divide and develop (differentiate) into one or more specialized cell types`,`only exist in adult bone marrow`,`never divide again once formed`], ans:1, exp:`Stem cells can both self-renew (divide to make more stem cells) and differentiate into various specialized cell types depending on the type of stem cell.` },
      { q:`The process by which an unspecialized stem cell becomes a specific cell type, like a muscle cell or neuron, is called:`, ch:[`fertilization`,`replication`,`differentiation`,`mutation`], ans:2, exp:`Differentiation is the process through which a stem cell activates specific genes and changes in structure and function to become a specialized cell type.` },
      { q:`A "totipotent" cell, such as a fertilized egg in its earliest divisions, has the potential to:`, ch:[`only become skin cells`,`differentiate into only blood cell types`,`differentiate into no cell types at all`,`develop into any cell type in the body, including forming an entire new organism`], ans:3, exp:`Totipotent cells have the broadest potential of any cell, capable of giving rise to every cell type in the body as well as extra-embryonic tissues, forming a complete organism.` },
      { q:`Embryonic stem cells are generally described as "pluripotent," meaning they can:`, ch:[`differentiate into almost any cell type in the body, but cannot form an entire new organism on their own`,`only become one very specific cell type`,`never divide once removed from the embryo`,`only exist for a few hours before dying`], ans:0, exp:`Pluripotent stem cells can become almost any cell type in the body, but unlike totipotent cells, they cannot on their own develop into a complete new organism.` },
      { q:`Adult stem cells found in tissues like bone marrow are usually described as "multipotent" because they can:`, ch:[`convert directly into muscle tissue`,`differentiate into a limited range of related cell types, such as various blood cell types`,`become any cell type in the entire body`,`only divide a single time`], ans:1, exp:`Adult stem cells are typically multipotent, meaning they differentiate into a more limited set of related cell types, such as bone marrow stem cells mainly giving rise to blood cell types.` },
      { q:`Bone marrow transplants, sometimes used to treat blood cancers like leukemia, work by introducing:`, ch:[`only white blood cells with no stem cell activity`,`fully mature red blood cells only`,`healthy hematopoietic (blood-forming) stem cells that can regenerate a patient's blood and immune cells`,`synthetic plastic cells`], ans:2, exp:`Bone marrow transplants provide healthy hematopoietic stem cells, which can differentiate into all the blood cell types the patient needs, replacing a damaged blood-forming system.` },
      { q:`Compared to adult stem cells, embryonic stem cells are generally considered to have:`, ch:[`identical potential in every way`,`no ability to differentiate at all`,`less differentiation potential`,`greater differentiation potential, since they are pluripotent rather than multipotent`], ans:3, exp:`Embryonic stem cells are pluripotent and can become nearly any cell type, while most adult stem cells are multipotent, limited to a narrower range of related cell types.` },
      { q:`A major ethical debate surrounding embryonic stem cell research stems from the fact that:`, ch:[`obtaining embryonic stem cells traditionally has involved the destruction of early-stage embryos`,`embryonic stem cells cannot be studied in a lab`,`embryonic stem cells have never shown any medical potential`,`the research requires no embryos at any stage`], ans:0, exp:`Deriving embryonic stem cells has traditionally required using early-stage embryos, which are destroyed in the process, raising ethical questions for many people.` },
      { q:`Induced pluripotent stem cells (iPSCs) are created by:`, ch:[`combining stem cells from two different species`,`reprogramming adult body cells (such as skin cells) in the lab to behave like pluripotent embryonic stem cells`,`extracting cells directly from a human embryo`,`cloning an entire adult organism`], ans:1, exp:`iPSCs are made by taking ordinary adult cells, such as skin cells, and reprogramming them in the lab so they revert to a pluripotent, embryonic-like state, without using embryos.` },
      { q:`One reason scientists are excited about induced pluripotent stem cells is that they may:`, ch:[`replace the need for bone marrow entirely`,`completely eliminate the need for any further stem cell research`,`allow researchers to study diseases and test treatments using a patient's own reprogrammed cells, avoiding some ethical and rejection issues`,`only be used to study plant biology`], ans:2, exp:`Because iPSCs can be made from a patient's own adult cells, they avoid ethical concerns tied to embryo use and may reduce immune rejection risk if used for that patient's treatment.` },
      { q:`Regenerative medicine, a major goal of stem cell research, aims to:`, ch:[`eliminate the need for any medical treatment`,`prevent all cells in the body from ever dividing`,`replace stem cells entirely with synthetic materials`,`repair or replace damaged tissues and organs using stem cells or cells derived from them`], ans:3, exp:`Regenerative medicine seeks to use stem cells' ability to differentiate into needed cell types to repair or regenerate damaged tissues and organs.` },
    ]
  },
];
